let diarioLog = JSON.parse(localStorage.getItem(STORAGE_KEY_DIARIO)) || [];
let comprasEstado = JSON.parse(localStorage.getItem(STORAGE_KEY_COMPRAS)) || [];

function atualizarProgressoDiarioGlobais() {
    const dataHoje = new Date().toISOString().split('T')[0];
    const logsHoje = diarioLog.filter(log => log.data === dataHoje);
    let kcalTotal = 0, pTotal = 0, cTotal = 0, gTotal = 0;
    
    logsHoje.forEach(l => { 
        kcalTotal += l.calorias || 0; 
        pTotal += l.prot || 0; 
        cTotal += l.carb || 0; 
        gTotal += l.gord || 0; 
    });
    
    if(document.getElementById('caloriasAtuais')) document.getElementById('caloriasAtuais').innerText = kcalTotal;
    if(document.getElementById('protAtual')) document.getElementById('protAtual').innerText = pTotal;
    if(document.getElementById('carbAtual')) document.getElementById('carbAtual').innerText = cTotal;
    if(document.getElementById('gordAtual')) document.getElementById('gordAtual').innerText = gTotal;
    
    if(document.getElementById('barraProgresso')) {
        let percentual = (kcalTotal / META_CALORIAS) * 100;
        document.getElementById('barraProgresso').style.width = (percentual > 100 ? 100 : percentual) + '%';
        document.getElementById('barraProgresso').className = kcalTotal > META_CALORIAS ? "bg-red-400 h-3 rounded-full transition-all duration-500" : "bg-white h-3 rounded-full transition-all duration-500";
    }
}